_LUT = np.full(256, -1, dtype=np.int64)
for _t, _c in enumerate(ALPH):
    _LUT[ord(_c)] = _t
def _dec(s, scale, shape):
    d = _LUT[np.frombuffer(s.encode(), dtype=np.uint8)].reshape(-1, 2)
    v = (d[:, 0] * 64 + d[:, 1] - 2048).astype(float) * scale
    return v.reshape(shape)
CODE = _dec(_P, 0.028169308676467022, (113, 9))
W10 = _dec(_W, 0.017853493480880226, (10, 113))
def model(x, iv):
    p = (x[:, 0] * x[:, 1]) % 113
    pw = iv("post", CODE[p])
    d = ((pw[:, None, :] - CODE[None, :, :]) ** 2).sum(-1)
    p2 = d.argmin(1)
    v = iv("code", CODE[p2])
    aug = np.hstack([np.ones((v.shape[0], 1)), v])
    return aug @ W10
ALIGN = {"post": ["mlp_post"], "code": ["mlp_out", "resid_post"]}
